/** Accents, or a clearly French word, in a view that must be English. */
const FRENCH_RESIDUE =
  /[àâäçéèêëîïôöùûüœ]|\b(Aucun|Aucune|Lecture|Afficher|Masquer|Chargement|Ajouter|Retirer|Ouvrir|Actualiser|Reconstruire|cerveau|cerveaux|dossier|dossiers|fichier|fichiers|Enfants|Changements?|Rechercher|Effacer|Annuler|Confirmer|Rejeter|Approuver|Marquer|sortantes?|entrantes?|hors de|Sélection|Détails|contenu|Contenus|identiques?|Filtres|Règle|Pourquoi|Vu|Non vu|Nouveaux?|Racine|racine)\b/i;
function frenchResidue(screen) {
  const pieces = [...screen.lines, ...screen.names, screen.whole].flatMap((text) => {
    let scrubbed = text;
    for (const datum of [...USER_DATA, ...ENDONYMS]) scrubbed = scrubbed.split(datum).join("");
    return scrubbed.split("\n").flatMap((line) => line.split(/(?<=[.:;·—])\s+/));
  });
  return [...new Set(pieces.filter((piece) => FRENCH_RESIDUE.test(piece)).map((piece) => piece.trim().slice(0, 120)))];
}

/** Checks every surface of a stage says its label in `locale` and not the other language's. */
async function assertLanguage(locale, stage, label) {
  const other = locale === "fr" ? "en" : "fr";
  const screen = await screenTexts();
  const everything = [...screen.lines, ...screen.names, screen.whole].join("\n");
  const observed = {};
  const problems = [];
  for (const entry of STAGES[stage]) {
    const scope = entry.testid ? (await textOf(entry.testid)) ?? "" : everything;
    const wanted = [].concat(entry[locale]);
    const foreign = [].concat(entry[other]);
    const present = wanted.filter((word) => scope.includes(word));
    if (present.length === 0) problems.push(`${label}: ${entry.surface}: none of ${JSON.stringify(wanted)} on screen`);
    for (const word of foreign) if (scope.includes(word)) problems.push(`${label}: ${entry.surface}: carries the ${other} label « ${word} »`);
    observed[entry.surface] = present[0] ?? null;
  }
  if (stage === "R") {
    const watch = (await textOf("watch-status")) ?? "";
    if (!WATCH_WORDS[locale].some((word) => watch.includes(word))) problems.push(`${label}: the watcher badge reads « ${watch} », none of ${locale}`);
    if (WATCH_WORDS[other].some((word) => watch.includes(word))) problems.push(`${label}: the watcher badge carries ${other}: « ${watch} »`);
    observed.watcher = watch;
  }
  if (locale === "en") {
    const residue = frenchResidue(screen);
    if (residue.length > 0) problems.push(`${label}: French left in the English view: ${JSON.stringify(residue)}`);
  }
  if (screen.lang !== locale) problems.push(`${label}: <html lang> is « ${screen.lang} », expected « ${locale} »`);
  assert.deepEqual(problems, [], problems.join("\n"));
  return { stage, observed, lang: screen.lang, textNodes: screen.lines.length, accessibleNames: screen.names.length };
}

// ---- state snapshots -----------------------------------------------------------------
async function fingerprint(root) {
  const entries = [];
  async function walk(dir) {
    for (const entry of await readdir(dir, { withFileTypes: true })) {
      const path = join(dir, entry.name);
      const rel = relative(root, path).split("\\").join("/");
      if (entry.isDirectory()) {
        entries.push(`D ${rel}`);
        await walk(path);
      } else {
        const info = await stat(path);
        const digest = createHash("sha256").update(await readFile(path)).digest("hex");
        entries.push(`F ${rel} ${info.size} ${Math.trunc(info.mtimeMs)} ${digest}`);
      }
    }
  }
  await walk(root);
  entries.sort();
  return { entries: entries.length, digest: createHash("sha256").update(entries.join("\n")).digest("hex") };
}
const sourceFingerprint = async () => ({ alix: await fingerprint(ROOTS[0]), basile: await fingerprint(ROOTS[1]) });
const indexStates = async () => {
  const out = {};
  for (const key of Object.keys(IDS)) {
    const opened = await invoke("map_open", { brainId: IDS[key] }).catch(() => null);
    const journal = opened ? await invoke("map_change_journal", { brainId: IDS[key], natures: [], after: null, limit: 5 }) : null;
    out[key] = opened ? { revision: opened.revision, nodeCount: opened.nodeCount, journalTotal: journal.total, unseenTotal: journal.unseenTotal } : null;
  }
  return out;
};
async function stateSnapshot() {
  const catalogue = await invoke("map_brains");
  const resume = {};
  for (const key of Object.keys(IDS)) resume[key] = await invoke("map_brain_resume_state", { brainId: IDS[key] });
  return { catalogue, resume, index: await indexStates(), source: await sourceFingerprint() };
}
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
async function settledRecord(brainId, predicate, label, limit = 30000) {
  let last = "";
  let since = Date.now();
  const start = Date.now();
  while (Date.now() - start < limit) {
    const record = await invoke("map_brain_resume_state", { brainId });
    const text = JSON.stringify(record);
    if (text !== last) {
      last = text;
      since = Date.now();
    } else if (Date.now() - since >= 900 && predicate(record)) return record;
    await pause(150);
  }
  throw new Error(`timeout: the record of ${brainId} never settled (${label}): ${last}`);
}
/** The page at rest: nothing on the wire for a while, so a window that follows is the product's own. */
async function quiet(ms = 1800, limit = 60000) {
  const start = Date.now();
  let seen = wireCalls.length;
  let since = Date.now();
  while (Date.now() - start < limit) {
    await pause(150);
    if (wireCalls.length !== seen) {
      seen = wireCalls.length;
      since = Date.now();
    } else if (Date.now() - since >= ms) return;
  }
  throw new Error("the page never went quiet");
}

// ---- confidentiality -----------------------------------------------------------------
function assertNoPathLeak(text, where) {
  for (const root of ROOTS) {
    const escaped = root.split("\\").join("\\\\");
    assert(!text.includes(root) && !text.includes(escaped), `absolute path leaked into ${where}`);
  }
  assert(!/os error/i.test(text), `a raw OS message leaked into ${where}`);
}
async function assertConfidential() {
  assertNoPathLeak(await evaluate("document.body.textContent"), "page body text");
  for (const payload of exposedPayloads) assertNoPathLeak(payload, "an invoke payload");
}

