/** The bounded map shows a folder's files only once it is explored, so a file is found the way a person finds it: by search. */
const nodeByName = async (key, name) => {
  const page = await invoke("map_search_nodes", { brainId: IDS[key], query: name, offset: 0, limit: 50 });
  return page.items.find((hit) => hit.name === name) ?? null;
};
async function typeInSearch(query) {
  const current = await evaluate(`document.querySelector('[data-testid="search-input"]').value`);
  if (current === query) return;
  await click(testid("search-input"));
  await selectAll();
  await typeText(query);
}
async function selectByClick(key, name) {
  const node = await nodeByName(key, name);
  assert(node, `${key} has a node named ${name}`);
  await typeInSearch(name);
  await untilTrue(`the search offers ${name}`, () =>
    evaluate(`[...document.querySelectorAll('[data-testid="search-hit"]')].some((b) => b.getAttribute('data-node-id') === '${node.nodeId}')`), 30000);
  await click(`[data-testid="search-hit"][data-node-id="${node.nodeId}"]`);
  await untilTrue(`${name} selected in ${key}`, async () => (await screenSelection()).selectedId === node.nodeId, 60000);
  return node.nodeId;
}
const shownAlone = (brainId, needNodes) => async () => {
  const s = await screenSelection();
  return s.chips.length === 1 && s.chips[0] === brainId && (!needNodes || s.nodeIds.length > 0);
};
/** Moving from one brain to the other, by the composition bar — the language is not the brain's. */
async function switchTo(toKey, fromKey, { needNodes = true } = {}) {
  await click(testid("composition-add-trigger"));
  await until(`!!document.querySelector('[data-testid="composition-add-item-${IDS[toKey]}"]')`);
  await click(testid(`composition-add-item-${IDS[toKey]}`));
  await until(`!!document.querySelector('[data-testid="composition-chip-${IDS[toKey]}"]')`);
  await pause(600);
  await click(testid(`composition-remove-${IDS[fromKey]}`));
  await untilTrue(`${toKey} shown alone`, shownAlone(IDS[toKey], needNodes), 60000);
  await pause(800);
}

/**
 * The switch itself: a REAL click on the language button, judged over a window in which the
 * harness makes no call of its own — every `map_*` command in it would be the product's, and
 * none is allowed.
 */
async function switchLanguage(to) {
  await quiet();
  const before = { snapshot: await stateSnapshot(), selection: await screenSelection(), screen: await screenTexts() };
  await quiet();
  const from = wireCalls.length;
  const clickedAt = Date.now();
  await click(testid(`language-${to}`));
  await pause(2200);
  const window = wireCalls.slice(from).map((call) => call.command);
  const storage = await storageState();
  const lang = await evaluate("document.documentElement.lang");
  const pressed = await evaluate(`document.querySelector(${JSON.stringify(testid(`language-${to}`))}).getAttribute('aria-pressed')`);
  const selectionAfter = await screenSelection();
  const screenAfter = await screenTexts();
  const snapshotAfter = await stateSnapshot();
  const problems = [];
  if (window.length !== 0) problems.push(`the switch caused backend commands: ${window.join(", ")}`);
  if (lang !== to) problems.push(`<html lang> is « ${lang} », expected « ${to} »`);
  if (pressed !== "true") problems.push(`the ${to} button is not pressed`);
  if (storage.locale !== to) problems.push(`localStorage[filetopo.locale] is « ${storage.locale} », expected « ${to} »`);
  if (!(storage.length === 1 && storage.keys[0] === "filetopo.locale")) problems.push(`the browser's storage holds ${JSON.stringify(storage.keys)}, expected only filetopo.locale`);
  if (storage.session !== 0) problems.push(`sessionStorage holds ${storage.session} key(s)`);
  if (!same(before.snapshot.catalogue, snapshotAfter.catalogue)) problems.push("the catalogue (brains, identities, active brain) moved");
  if (!same(before.snapshot.resume, snapshotAfter.resume)) problems.push("a resume record moved");
  if (!same(before.snapshot.index, snapshotAfter.index)) problems.push("an Index revision, a node count or a journal total moved");
  if (!same(before.snapshot.source, snapshotAfter.source)) problems.push("the source moved");
  if (!same(before.selection, selectionAfter)) problems.push(`the selection / brain / counts moved: ${JSON.stringify(before.selection)} → ${JSON.stringify(selectionAfter)}`);
  const userDataBefore = USER_DATA.map((datum) => countOf(before.screen.whole, datum));
  const userDataAfter = USER_DATA.map((datum) => countOf(screenAfter.whole, datum));
  if (!same(userDataBefore, userDataAfter)) problems.push(`the names shown changed: ${JSON.stringify(userDataBefore)} → ${JSON.stringify(userDataAfter)}`);
  assert.deepEqual(problems, [], problems.join("\n"));
  return {
    to,
    realClick: true,
    commandsSentByTheProductDuringTheSwitch: window,
    settleMs: Date.now() - clickedAt,
    htmlLang: lang,
    pressedButton: `language-${to}`,
    storage,
    userDataOccurrencesBefore: Object.fromEntries(USER_DATA.map((d, i) => [d, userDataBefore[i]]).filter(([, n]) => n > 0)),
    userDataOccurrencesAfter: Object.fromEntries(USER_DATA.map((d, i) => [d, userDataAfter[i]]).filter(([, n]) => n > 0)),
    stateUnchanged: {
      catalogue: true,
      resumeRecords: true,
      indexRevisionsAndJournalTotals: true,
      sourceSha256: true,
      selectionBrainAndCounts: true,
    },
    selection: selectionAfter,
    indexAndJournal: snapshotAfter.index,
  };
}

/** Brings the large surfaces of a stage on screen — each opened by a real click if it is not already. */
async function openSurfaces(stage) {
  await ensureExpanded("journal-toggle");
  await until(`!!document.querySelector('[data-testid="journal-total"]')`, 30000);
  await ensureExpanded("open-review-queue");
  await until(`!!document.querySelector('[data-testid="review-empty"]') || !!document.querySelector('[data-testid="review-position"]')`, 30000);
  await until(`!!document.querySelector('[data-testid="open-duplicate-explorer"]') || !!document.querySelector('.duplicates [role="alert"]')`, 30000);
  if (await exists("open-duplicate-explorer")) {
    await ensureExpanded("open-duplicate-explorer");
    await until(`!!document.querySelector('[data-testid="duplicate-summary"]') || !!document.querySelector('[data-testid="duplicates-not-observed"]')`, 30000);
  }
  await typeInSearch(stage === "R" ? "report" : "note");
  await until(`!!document.querySelector('[data-testid="search-total"]') || !!document.querySelector('[data-testid="search-results"]')`, 30000);
  if (!(await exists("filter-count"))) {
    await click(testid("filter-state-NEW"));
    await until(`!!document.querySelector('[data-testid="filter-count"]')`, 30000);
  }
  await pause(500);
}

const results = { phase };
async function debugScreen() {
  try {
    return await evaluate(`(() => {
      const french = /[àâäçéèêëîïôöùûüœ]|\\b(Afficher|hors de|Cerveau|dossier)\\b/i;
      const found = [];
      const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
      for (let n = walker.nextNode(); n; n = walker.nextNode()) {
        if (!french.test(n.textContent)) continue;
        const chain = [];
        for (let p = n.parentElement; p && chain.length < 5; p = p.parentElement) {
          chain.push(p.tagName + (typeof p.className === "string" && p.className ? "." + p.className : "") + (p.getAttribute("data-testid") ? "#" + p.getAttribute("data-testid") : ""));
        }
        found.push({ text: n.textContent.slice(0, 100), chain });
      }
      return {
        status: document.querySelector(".app__status")?.textContent ?? null,
        lang: document.documentElement.lang,
        frenchTextNodes: found.slice(0, 25),
      };
    })()`);
  } catch {
    return null;
  }
}
